# ---------------------------------------------------------------------------
# COM readback helpers (STA / main thread)
# ---------------------------------------------------------------------------


def _a1(row: int, col: int) -> str:
    """Return the A1 address for a 1-based ``(row, col)`` pair."""

    return f"{_COLUMNS[col - 1]}{row}"


def _is_date_format(number_format: str) -> bool:
    """Return ``True`` when ``number_format`` is a date/time format."""

    lowered = number_format.lower()
    if lowered in ("general", ""):
        return False
    return any(token in lowered for token in _DATE_FORMAT_TOKENS)


def _serial_to_iso(serial: float) -> str:
    """Convert an Excel 1900-system date serial to an ISO ``YYYY-MM-DD`` string."""

    return (_EXCEL_EPOCH + dt.timedelta(days=float(serial))).isoformat()


def _read_cell(sheet: Any, address: str) -> dict[str, Any]:
    """Read one cell from Excel and normalize it into the manifest shape."""

    cell = sheet.Range(address)
    raw = cell.Value2
    number_format = str(cell.NumberFormat)
    has_formula = bool(cell.HasFormula)

    kind: str
    value: Any
    if raw is None:
        kind, value = "empty", None
    elif isinstance(raw, bool):
        kind, value = "boolean", raw
    elif isinstance(raw, int) and raw in EXCEL_ERROR_CODES:
        kind, value = "error", EXCEL_ERROR_CODES[raw]
    elif isinstance(raw, (int, float)):
        if _is_date_format(number_format):
            kind, value = "date", _serial_to_iso(float(raw))
        else:
            kind, value = "number", float(raw)
    elif isinstance(raw, str):
        kind, value = "string", raw
    else:  # pragma: no cover - defensive; unexpected Variant type
        kind, value = "string", str(raw)

    return {
        "kind": kind,
        "value": value,
        "number_format": number_format,
        "has_formula": has_formula,
        "formula": str(cell.Formula) if has_formula else None,
    }


def _read_validation(sheet: Any, address: str) -> dict[str, Any]:
    """Read the data-validation rule anchored at ``address``."""

    validation = sheet.Range(address).Validation
    return {
        "range": address,
        "type": int(validation.Type),
        "operator": int(validation.Operator),
        "formula1": str(validation.Formula1),
        "formula2": str(validation.Formula2),
        "ignore_blank": bool(validation.IgnoreBlank),
        "in_cell_dropdown": bool(validation.InCellDropdown),
        "alert_style": int(validation.AlertStyle),
    }


def _read_format_conditions(sheet: Any, address: str) -> list[dict[str, Any]]:
    """Read every conditional-formatting rule applied to ``address``."""

    conditions = sheet.Range(address).FormatConditions
    rules: list[dict[str, Any]] = []
    for index in range(1, int(conditions.Count) + 1):
        rule = conditions.Item(index)
        rule_type = int(rule.Type)
        operator: int | None
        try:
            operator = int(rule.Operator)
        except Exception:  # noqa: BLE001 - xlExpression rules ignore Operator
            operator = None
        color: int | None = None
        try:
            color = int(rule.Interior.Color)
        except Exception:  # noqa: BLE001 - no fill set
            color = None
        rules.append(
            {
                "range": address,
                "priority": int(rule.Priority),
                "type": rule_type,
                "operator": operator,
                "formula1": str(rule.Formula1),
                "stop_if_true": bool(rule.StopIfTrue),
                "applies_to": str(rule.AppliesTo.Address),
                "interior_color": color,
            }
        )
    return rules


def _read_list_object(sheet: Any, name: str) -> dict[str, Any]:
    """Read the identity, geometry and column headers of a ListObject."""

    table = sheet.ListObjects(name)
    headers = [
        str(table.HeaderRowRange.Cells(1, col).Value2)
        for col in range(1, int(table.ListColumns.Count) + 1)
    ]
    return {
        "name": str(table.Name),
        "sheet": str(sheet.Name),
        "range": str(table.Range.Address),
        "header_row": str(table.HeaderRowRange.Address),
        "data_body": str(table.DataBodyRange.Address),
        "headers": headers,
    }


# ---------------------------------------------------------------------------
# RangesCellsProject.xlsm builder
# ---------------------------------------------------------------------------


def _write_block(sheet: Any, address: str, values: list[list[Any]]) -> None:
    """Write a 2-D list of values into ``address`` via ``Value2``."""

    rows = len(values)
    cols = len(values[0])
    top_left = sheet.Range(address).Cells(1, 1)
    bottom_right = sheet.Range(address).Cells(rows, cols)
    sheet.Range(top_left, bottom_right).Value2 = values


def _build_ranges_cells_sheet(sheet: Any) -> None:
    """Populate the ``Cells`` sheet with the deterministic Phase 2 range content."""

    # Column labels (rows 1..15) describe each scalar in column B.
    labels = [
        "string",
        "integer",
        "decimal",
        "boolean_true",
        "boolean_false",
        "blank",
        "equals_string",
        "formula_sum",
        "formula_div0",
        "formula_na",
        "formula_ref",
        "date_value",
        "datetime_value",
        "number_not_date",
    ]
    for index, label in enumerate(labels, start=2):
        sheet.Range(f"A{index}").Value2 = label

    # Constants. Column A carries the label, column B the value.
    sheet.Range("B2").Value2 = "hello world"
    sheet.Range("B3").Value2 = 42
    sheet.Range("B3").NumberFormat = "0"
    sheet.Range("B4").Value2 = 3.14
    sheet.Range("B4").NumberFormat = "0.00"
    sheet.Range("B5").Value2 = True
    sheet.Range("B6").Value2 = False
    # B7 stays empty on purpose.

    # A literal '='-prefixed *text* cell. Forcing the Text number format keeps
    # Excel from parsing the assignment as a formula (verified on 16.0.14332).
    sheet.Range("B8").NumberFormat = "@"
    sheet.Range("B8").Value2 = "=1+1"
    sheet.Range("B8").NumberFormat = "General"

    # Formulas (the only path that creates a real formula).
    sheet.Range("B9").Formula = "=1+2"
    sheet.Range("B10").Formula = "=1/0"
    sheet.Range("B11").Formula = "=NA()"
    sheet.Range("B12").Formula = "=B3*2"

    # Real dates written as serials with date number formats (no locale drift).
    for address, serial in RANGES_DATE_SERIALS.items():
        sheet.Range(address).Value2 = float(serial)
    sheet.Range("B13").NumberFormat = "yyyy-mm-dd"
    sheet.Range("B14").NumberFormat = "yyyy-mm-dd hh:mm"

    # A date-shaped serial with a plain numeric format: must read as a number.
    sheet.Range("B15").Value2 = 45000.0
    sheet.Range("B15").NumberFormat = "General"

    # 2-D block.
    _write_block(sheet, RANGES_BLOCK["address"], RANGES_BLOCK["values"])

    # Merged area with an anchor value.
    sheet.Range(RANGES_MERGED["address"]).Merge()
    sheet.Range(RANGES_MERGED["anchor"]).Value2 = RANGES_MERGED["value"]

    # Data validation: inline list and whole-number between.
    list_validation = sheet.Range(RANGES_VALIDATION[0]["range"]).Validation
    list_validation.Delete()
    list_validation.Add(
        RANGES_VALIDATION[0]["type"],
        RANGES_VALIDATION[0]["alert_style"],
        RANGES_VALIDATION[0]["operator"],
        RANGES_VALIDATION[0]["formula1"],
    )
    list_validation.InCellDropdown = RANGES_VALIDATION[0]["in_cell_dropdown"]

    whole_validation = sheet.Range(RANGES_VALIDATION[1]["range"]).Validation
    whole_validation.Delete()
    whole_validation.Add(
        RANGES_VALIDATION[1]["type"],
        RANGES_VALIDATION[1]["alert_style"],
        RANGES_VALIDATION[1]["operator"],
        RANGES_VALIDATION[1]["formula1"],
        RANGES_VALIDATION[1]["formula2"],
    )
    # ``InCellDropdown`` defaults to True for *every* validation type on this
    # build; set it explicitly so the readback matches the design.
    whole_validation.InCellDropdown = RANGES_VALIDATION[1]["in_cell_dropdown"]

    # Conditional formatting: one cell-value rule and one expression rule.
    cell_value_cf = sheet.Range(RANGES_CONDITIONAL_FORMATTING[0]["range"]).FormatConditions
    cell_value_cf.Delete()
    value_rule = cell_value_cf.Add(
        RANGES_CONDITIONAL_FORMATTING[0]["type"],
        RANGES_CONDITIONAL_FORMATTING[0]["operator"],
        RANGES_CONDITIONAL_FORMATTING[0]["formula1"],
    )
    value_rule.Interior.Color = RANGES_CONDITIONAL_FORMATTING[0]["interior_color"]
    value_rule.StopIfTrue = RANGES_CONDITIONAL_FORMATTING[0]["stop_if_true"]

    expression_cf = sheet.Range(RANGES_CONDITIONAL_FORMATTING[1]["range"]).FormatConditions
    expression_rule = expression_cf.Add(
        RANGES_CONDITIONAL_FORMATTING[1]["type"],
        XL_COND_BETWEEN,
        RANGES_CONDITIONAL_FORMATTING[1]["formula1"],
    )
    expression_rule.Interior.Color = RANGES_CONDITIONAL_FORMATTING[1]["interior_color"]
    expression_rule.StopIfTrue = RANGES_CONDITIONAL_FORMATTING[1]["stop_if_true"]

    # ListObject with header + rows.
    _write_block(sheet, "T1:V4", [RANGES_LIST_OBJECT["headers"], *RANGES_LIST_OBJECT["rows"]])
    table = sheet.ListObjects.Add(1, sheet.Range(RANGES_LIST_OBJECT["range"]), False, 1)
    table.Name = RANGES_LIST_OBJECT["name"]


def _build_struct_ops_sheet(sheet: Any) -> None:
    """Populate the ``StructOps`` sheet with structural-operation targets."""

    sheet.Range("A1").Value2 = "copy_source"
    _write_block(sheet, STRUCT_BLOCK["address"], STRUCT_BLOCK["values"])

    sheet.Range("D1").Value2 = "copy_dest"
    # D2:E4 intentionally left empty as the copy destination.

    sheet.Range("G1").Value2 = "shift_block"
    _write_block(sheet, STRUCT_SHIFT_BLOCK["address"], STRUCT_SHIFT_BLOCK["values"])

    sheet.Range("J1").Value2 = "merge_block"
    _write_block(sheet, STRUCT_MERGE["address"], STRUCT_MERGE["values"])

    sheet.Range("J4").Value2 = "unmerge_block"
    sheet.Range(STRUCT_PREMERGED["address"]).Merge()
    sheet.Range(STRUCT_PREMERGED["anchor"]).Value2 = STRUCT_PREMERGED["value"]


def _add_vba_module(workbook: Any, module_name: str, source: str) -> str:
    """Add a deterministic standard module through VBIDE; return a status string."""

    try:
        project = workbook.VBProject
        component = project.VBComponents.Add(VB_COMPONENT_STANDARD)
        component.Name = module_name
        component.CodeModule.AddFromString(source)
    except Exception as exc:  # noqa: BLE001 - VBOM trust may be unavailable
        return f"unavailable: {exc.__class__.__name__}"
    return "added"


def _build_ranges_cells_project(app: Any, target: Path) -> dict[str, Any]:
    """Build ``RangesCellsProject.xlsm`` at ``target`` and return build notes."""

    workbook = app.Workbooks.Add()
    try:
        # Collapse the default template to a single, deterministically named sheet.
        while int(workbook.Worksheets.Count) > 1:
            workbook.Worksheets(workbook.Worksheets.Count).Delete()
        cells = workbook.Worksheets(1)
        cells.Name = RANGES_SHEET
        _build_ranges_cells_sheet(cells)

        struct = workbook.Worksheets.Add(After=workbook.Worksheets(workbook.Worksheets.Count))
        struct.Name = STRUCT_SHEET
        _build_struct_ops_sheet(struct)

        vba_status = _add_vba_module(workbook, "modFixtureInfo", RANGES_VBA_SOURCE)

        workbook.SaveAs(str(target), XLSM_FILE_FORMAT)
        workbook.Save()
    finally:
        workbook.Close(SaveChanges=False)

    return {"vba_module": vba_status, "sheets": [RANGES_SHEET, STRUCT_SHEET]}


# ---------------------------------------------------------------------------
# PivotTablesProject.xlsm builder
# ---------------------------------------------------------------------------


def _build_pivottables_project(app: Any, target: Path) -> dict[str, Any]:
    """Build ``PivotTablesProject.xlsm`` at ``target`` and return build notes."""

    workbook = app.Workbooks.Add()
    try:
        while int(workbook.Worksheets.Count) > 1:
            workbook.Worksheets(workbook.Worksheets.Count).Delete()
        source = workbook.Worksheets(1)
        source.Name = PIVOT_SOURCE_SHEET

        # Local worksheet source: headers + deterministic rows.
        for col, header in enumerate(PIVOT_SOURCE_HEADERS, start=1):
            source.Cells(1, col).Value2 = header
        for row_index, row in enumerate(PIVOT_SOURCE_ROWS, start=2):
            for col, value in enumerate(row, start=1):
                source.Cells(row_index, col).Value2 = value

        # Local ListObject-backed source for the third cache.
        table_sheet = workbook.Worksheets.Add(After=workbook.Worksheets(workbook.Worksheets.Count))
        table_sheet.Name = PIVOT_TABLE_SHEET
        for col, header in enumerate(PIVOT_SOURCE_HEADERS, start=1):
            table_sheet.Cells(1, col).Value2 = header
        for row_index, row in enumerate(PIVOT_SOURCE_ROWS, start=2):
            for col, value in enumerate(row, start=1):
                table_sheet.Cells(row_index, col).Value2 = value
        list_object = table_sheet.ListObjects.Add(1, table_sheet.Range("A1:E7"), False, 1)
        list_object.Name = PIVOT_LIST_OBJECT

        report = workbook.Worksheets.Add(After=workbook.Worksheets(workbook.Worksheets.Count))
        report.Name = PIVOT_REPORT_SHEET

        caches = workbook.PivotCaches()
        # Cache 1: worksheet range (shared by ptA and ptB).
        cache_one = caches.Add(1, source.Range("A1:E7"))
        # Cache 2: ListObject-backed range.
        cache_two = caches.Add(1, table_sheet.ListObjects(PIVOT_LIST_OBJECT).Range)

        for spec in PIVOT_TABLES:
            cache = cache_one if spec["cache_index"] == 1 else cache_two
            pivot = report.PivotTables().Add(cache, report.Range(spec["anchor"]), spec["name"])
            for field in spec["row_fields"]:
                pivot.PivotFields(field).Orientation = XL_FIELD_ROW
            for field in spec["column_fields"]:
                pivot.PivotFields(field).Orientation = XL_FIELD_COLUMN
            for field in spec["page_fields"]:
                pivot.PivotFields(field).Orientation = XL_FIELD_PAGE
            for data_field in spec["data_fields"]:
                pivot.AddDataField(
                    pivot.PivotFields(data_field["source_name"]),
                    data_field["caption"],
                    data_field["function"],
                )
            if spec["page_current_page"] is not None:
                page_field = pivot.PivotFields(spec["page_fields"][0])
                page_field.CurrentPage = spec["page_current_page"]
            if spec["filter"] is not None:
                field = pivot.PivotFields(spec["filter"]["field"])
                items = field.PivotItems()
                for index in range(1, int(items.Count) + 1):
                    if str(items.Item(index).Value) in spec["filter"]["hidden_items"]:
                        items.Item(index).Visible = False

        vba_status = _add_vba_module(workbook, "modFixtureInfo", PIVOTS_VBA_SOURCE)

        workbook.SaveAs(str(target), XLSM_FILE_FORMAT)
        workbook.Save()
    finally:
        workbook.Close(SaveChanges=False)

    return {
        "vba_module": vba_status,
        "sheets": [PIVOT_SOURCE_SHEET, PIVOT_TABLE_SHEET, PIVOT_REPORT_SHEET],
    }


# ---------------------------------------------------------------------------
# Manifest readback + verification (the design oracle)
# ---------------------------------------------------------------------------


def _cell_expected(
    kind: str, value: Any, number_format: str, has_formula: bool, formula: str | None
) -> dict[str, Any]:
    """Build the expected cell record for a scalar fixture cell."""

    return {
        "kind": kind,
        "value": value,
        "number_format": number_format,
        "has_formula": has_formula,
        "formula": formula,
    }


def _design_scalar_cells() -> dict[str, dict[str, Any]]:
    """Return the design-expected per-cell records for the ``Cells`` sheet."""

    formulas = {address: formula for address, formula, _ in RANGES_FORMULAS}
    expected: dict[str, dict[str, Any]] = {}
    for address, kind, value, number_format in RANGES_CELLS:
        has_formula = address in formulas
        expected[address] = _cell_expected(
            kind, value, number_format, has_formula, formulas.get(address)
        )
    return expected


def _collect_ranges_cells(app: Any, path: Path) -> dict[str, Any]:
    """Reopen ``RangesCellsProject.xlsm`` read-only and collect the manifest block."""

    workbook = app.Workbooks.Open(
        str(path), UpdateLinks=0, ReadOnly=True, Notify=False, AddToMru=False
    )
    try:
        cells = workbook.Worksheets(RANGES_SHEET)
        expected_cells = _design_scalar_cells()

        actual_cells: dict[str, Any] = {}
        mismatches: list[dict[str, Any]] = []
        for address, expected in expected_cells.items():
            actual = _read_cell(cells, address)
            actual_cells[address] = actual
            if actual != expected:
                mismatches.append({"address": address, "expected": expected, "actual": actual})

        # 2-D block readback.
        block_rows = len(RANGES_BLOCK["values"])
        block_cols = len(RANGES_BLOCK["values"][0])
        top_left = cells.Range(RANGES_BLOCK["address"]).Cells(1, 1)
        bottom_right = cells.Range(RANGES_BLOCK["address"]).Cells(block_rows, block_cols)
        block_raw = cells.Range(top_left, bottom_right).Value2
        block_values = [[float(cell) for cell in row] for row in block_raw]

        # Merged area readback.
        merged_area = str(cells.Range(RANGES_MERGED["anchor"]).MergeArea.Address)
        merged_value = cells.Range(RANGES_MERGED["anchor"]).Value2
        # Compare in a locale-agnostic way: strip "$" and compare to the design.
        merged_matches = (
            merged_area.replace("$", "") == RANGES_MERGED["address"]
            and merged_value == RANGES_MERGED["value"]
        )

        validation = [_read_validation(cells, rule["range"]) for rule in RANGES_VALIDATION]
        conditional = _read_format_conditions(
            cells, RANGES_CONDITIONAL_FORMATTING[0]["range"]
        ) + _read_format_conditions(cells, RANGES_CONDITIONAL_FORMATTING[1]["range"])
        table = _read_list_object(cells, RANGES_LIST_OBJECT["name"])

        structural = workbook.Worksheets(STRUCT_SHEET)

        return {
            "sheets": [str(sheet.Name) for sheet in workbook.Worksheets],
            "cells": actual_cells,
            "cell_mismatches": mismatches,
            "block": {
                "address": RANGES_BLOCK["address"],
                "values": block_values,
                "matches": block_values == RANGES_BLOCK["values"],
            },
            "merged": {
                "address": merged_area,
                "anchor": RANGES_MERGED["anchor"],
                "value": merged_value,
                "matches": bool(merged_matches),
            },
            "data_validation": validation,
            "conditional_formatting": conditional,
            "list_object": table,
            "struct_ops": {
                "sheet": str(structural.Name),
                "copy_source": _read_cell(structural, "A2"),
                "copy_dest_empty": _read_cell(structural, "D2"),
                "shift_block": _read_cell(structural, "G2"),
                "merge_anchor": _read_cell(structural, "J2"),
                "premerged_merge_area": str(
                    structural.Range(STRUCT_PREMERGED["anchor"]).MergeArea.Address
                ),
            },
        }
    finally:
        workbook.Close(SaveChanges=False)


def _pivot_field_names(pivot: Any, collection_name: str) -> list[str]:
    """Return the ordered field names of one PivotTable orientation collection.

    Excel inserts a synthetic ``"Data"`` placeholder field into the row/column
    orientation collections when a PivotTable has two or more data fields. That
    placeholder has an error-code ``SourceName`` (``#N/A``) rather than a real
    source field name, so it is filtered out here to keep the layout list equal
    to the fields the fixture actually placed.
    """

    collection = getattr(pivot, collection_name)
    names: list[str] = []
    for index in range(1, int(collection.Count) + 1):
        source_name = collection.Item(index).SourceName
        if not isinstance(source_name, str):
            continue
        names.append(str(source_name))
    return names


def _read_pivot_table(pivot: Any, spec: dict[str, Any]) -> dict[str, Any]:
    """Read one PivotTable's identity, layout, aggregation and filter state."""

    cache = pivot.PivotCache()
    data_fields: list[dict[str, Any]] = []
    for index in range(1, int(pivot.DataFields.Count) + 1):
        field = pivot.DataFields.Item(index)
        data_fields.append(
            {
                "source_name": str(field.SourceName),
                "caption": str(field.Name),
                "function": int(field.Function),
                "position": int(field.Position),
            }
        )

    page_current_page: Any = None
    if int(pivot.PageFields.Count) > 0:
        page_field = pivot.PivotFields(_pivot_field_names(pivot, "PageFields")[0])
        page_current_page = str(page_field.CurrentPage.Value)

    filter_state: dict[str, Any] | None = None
    if spec["filter"] is not None:
        field = pivot.PivotFields(spec["filter"]["field"])
        hidden: list[str] = []
        visible: list[str] = []
        items = field.PivotItems()
        for index in range(1, int(items.Count) + 1):
            item = items.Item(index)
            if bool(item.Visible):
                visible.append(str(item.Value))
            else:
                hidden.append(str(item.Value))
        filter_state = {
            "field": str(field.SourceName),
            "all_items_visible": bool(field.AllItemsVisible),
            "visible_items": visible,
            "hidden_items": hidden,
        }

    return {
        "name": str(pivot.Name),
        "sheet": str(pivot.Parent.Name),
        "cache_index": int(pivot.CacheIndex),
        "cache_source_type": int(cache.SourceType),
        "cache_source_data": str(cache.SourceData),
        "table_range1": str(pivot.TableRange1.Address),
        "table_range2": str(pivot.TableRange2.Address),
        "row_fields": _pivot_field_names(pivot, "RowFields"),
        "column_fields": _pivot_field_names(pivot, "ColumnFields"),
        "page_fields": _pivot_field_names(pivot, "PageFields"),
        "page_current_page": page_current_page,
        "data_fields": data_fields,
        "filter": filter_state,
    }


def _collect_pivots(app: Any, path: Path) -> dict[str, Any]:
    """Reopen ``PivotTablesProject.xlsm`` read-only and collect the manifest block."""

    workbook = app.Workbooks.Open(
        str(path), UpdateLinks=0, ReadOnly=True, Notify=False, AddToMru=False
    )
    try:
        report = workbook.Worksheets(PIVOT_REPORT_SHEET)
        actual: dict[str, Any] = {}
        mismatches: list[dict[str, Any]] = []
        for spec in PIVOT_TABLES:
            pivot = report.PivotTables(spec["name"])
            record = _read_pivot_table(pivot, spec)
            actual[spec["name"]] = record

            expected_projection = {
                "cache_index": spec["cache_index"],
                "row_fields": spec["row_fields"],
                "column_fields": spec["column_fields"],
                "page_fields": spec["page_fields"],
                "data_fields": [
                    {
                        "source_name": field["source_name"],
                        "caption": field["caption"],
                        "function": field["function"],
                    }
                    for field in spec["data_fields"]
                ],
            }
            observed_projection = {
                "cache_index": record["cache_index"],
                "row_fields": record["row_fields"],
                "column_fields": record["column_fields"],
                "page_fields": record["page_fields"],
                "data_fields": [
                    {
                        "source_name": field["source_name"],
                        "caption": field["caption"],
                        "function": field["function"],
                    }
                    for field in record["data_fields"]
                ],
            }
            if observed_projection != expected_projection:
                mismatches.append(
                    {
                        "pivot_table": spec["name"],
                        "expected": expected_projection,
                        "actual": observed_projection,
                    }
                )

            if spec["filter"] is not None:
                expected_filter = {
                    "field": spec["filter"]["field"],
                    "hidden_items": spec["filter"]["hidden_items"],
                }
                observed_filter = record["filter"] or {}
                observed_projection = {
                    "field": observed_filter.get("field"),
                    "hidden_items": observed_filter.get("hidden_items"),
                }
                if observed_projection != expected_filter:
                    mismatches.append(
                        {
                            "pivot_table": spec["name"],
                            "expected_filter": expected_filter,
                            "actual_filter": observed_projection,
                        }
                    )

        caches: list[dict[str, Any]] = []
        cache_collection = workbook.PivotCaches()
        for index in range(1, int(cache_collection.Count) + 1):
            cache = cache_collection.Item(index)
            caches.append(
                {
                    "index": int(cache.Index),
                    "source_type": int(cache.SourceType),
                    "source_data": str(cache.SourceData),
                }
            )

        return {
            "sheets": [str(sheet.Name) for sheet in workbook.Worksheets],
            "pivot_report_sheet": PIVOT_REPORT_SHEET,
            "pivot_tables": actual,
            "pivot_mismatches": mismatches,
            "caches": caches,
            "source_list_object": _read_list_object(
                workbook.Worksheets(PIVOT_TABLE_SHEET), PIVOT_LIST_OBJECT
            ),
        }
    finally:
        workbook.Close(SaveChanges=False)


# ---------------------------------------------------------------------------
# Manifest assembly + orchestration
# ---------------------------------------------------------------------------


def _sha256(path: Path) -> str:
    """Return the hex SHA-256 of ``path``."""

    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for chunk in iter(lambda: handle.read(65536), b""):
            digest.update(chunk)
    return digest.hexdigest()


def _environment() -> dict[str, Any]:
    """Describe the fixture-authoring environment (build provenance)."""

    try:
        windows_version = f"{sys.getwindowsversion().major}.{sys.getwindowsversion().build}"
    except Exception:  # noqa: BLE001 - non-Windows fallback
        windows_version = platform.release()
    return {
        "python_version": platform.python_version(),
        "platform": platform.platform(),
        "windows_build": windows_version,
    }


def _build_manifest(
    *,
    app: Any,
    ranges_path: Path,
    pivots_path: Path,
    ranges_block: dict[str, Any],
    pivots_block: dict[str, Any],
    ranges_notes: dict[str, Any],
    pivots_notes: dict[str, Any],
) -> dict[str, Any]:
    """Assemble the committed manifest from the readback blocks."""

    excel_version = f"{app.Version}.{str(app.Build).split('.')[0]}"
    return {
        "schema_version": 1,
        "task": "task_041",
        "plan": ".ai/plans/plan_phase2_ranges_cells_pivottables.md",
        "generated_at": dt.datetime.now(dt.UTC).isoformat(timespec="seconds"),
        "target_excel_build": TARGET_EXCEL_BUILD,
        "observed_excel_version": excel_version,
        "generator": "tests/fixtures/build_phase2_fixtures.py",
        "environment": _environment(),
        "notes": [
            "Expected values are literal design constants in the generator; the "
            "generator asserts Excel readback equals them before committing.",
            "Fixtures are local/offline: no workbook connections, Power Query or Data Model.",
            "Excel is created hidden and non-activating; no Activate/Select is used.",
        ],
        "fixtures": {
            RANGES_FIXTURE: {
                "path": f"tests/fixtures/{RANGES_FIXTURE}",
                "sha256": _sha256(ranges_path),
                "size_bytes": ranges_path.stat().st_size,
                "build": ranges_notes,
                "sheets": ranges_block["sheets"],
                "cells": ranges_block["cells"],
                "cell_mismatches": ranges_block["cell_mismatches"],
                "block": ranges_block["block"],
                "merged": ranges_block["merged"],
                "data_validation": ranges_block["data_validation"],
                "conditional_formatting": ranges_block["conditional_formatting"],
                "list_object": ranges_block["list_object"],
                "list_object_ranges": {
                    "inside": RANGES_LIST_OBJECT["inside_ranges"],
                    "overlap": RANGES_LIST_OBJECT["overlap_ranges"],
                    "outside": RANGES_LIST_OBJECT["outside_ranges"],
                },
                "struct_ops": ranges_block["struct_ops"],
                "design": {
                    "scalar_cells": _design_scalar_cells(),
                    "formulas": {address: formula for address, formula, _ in RANGES_FORMULAS},
                    "date_serials": RANGES_DATE_SERIALS,
                    "block": {
                        "address": RANGES_BLOCK["address"],
                        "values": RANGES_BLOCK["values"],
                    },
                    "merged": RANGES_MERGED,
                    "validation": RANGES_VALIDATION,
                    "conditional_formatting": RANGES_CONDITIONAL_FORMATTING,
                    "list_object": RANGES_LIST_OBJECT,
                    "struct_ops": {
                        "copy_source": STRUCT_BLOCK,
                        "copy_dest": STRUCT_COPY_DEST,
                        "shift_block": STRUCT_SHIFT_BLOCK,
                        "merge": STRUCT_MERGE,
                        "premerged": STRUCT_PREMERGED,
                    },
                },
            },
            PIVOTS_FIXTURE: {
                "path": f"tests/fixtures/{PIVOTS_FIXTURE}",
                "sha256": _sha256(pivots_path),
                "size_bytes": pivots_path.stat().st_size,
                "build": pivots_notes,
                "sheets": pivots_block["sheets"],
                "pivot_report_sheet": pivots_block["pivot_report_sheet"],
                "pivot_tables": pivots_block["pivot_tables"],
                "pivot_mismatches": pivots_block["pivot_mismatches"],
                "caches": pivots_block["caches"],
                "source_list_object": pivots_block["source_list_object"],
                "design": {
                    "source_sheet": PIVOT_SOURCE_SHEET,
                    "source_headers": PIVOT_SOURCE_HEADERS,
                    "source_rows": PIVOT_SOURCE_ROWS,
                    "table_sheet": PIVOT_TABLE_SHEET,
                    "list_object": PIVOT_LIST_OBJECT,
                    "pivot_tables": PIVOT_TABLES,
                    "shared_cache": PIVOT_SHARED_CACHE,
                },
            },
        },
    }


def _verify_manifest(manifest: dict[str, Any]) -> list[str]:
    """Return a list of verification failures for a freshly built manifest."""

    failures: list[str] = []

    ranges = manifest["fixtures"][RANGES_FIXTURE]
    if ranges["cell_mismatches"]:
        failures.append(f"{RANGES_FIXTURE}: {len(ranges['cell_mismatches'])} cell mismatch(es)")
    if not ranges["block"]["matches"]:
        failures.append(f"{RANGES_FIXTURE}: 2-D block mismatch")
    if not ranges["merged"]["matches"]:
        failures.append(f"{RANGES_FIXTURE}: merged area mismatch")

    # Validation: type / operator / formulas / flags must match the design.
    validation_pairs = zip(ranges["design"]["validation"], ranges["data_validation"], strict=False)
    for expected, actual in validation_pairs:
        for key in (
            "range",
            "type",
            "operator",
            "formula1",
            "formula2",
            "ignore_blank",
            "in_cell_dropdown",
            "alert_style",
        ):
            if actual[key] != expected[key]:
                failures.append(
                    f"{RANGES_FIXTURE}: validation {expected['range']} {key} "
                    f"expected {expected[key]!r} got {actual[key]!r}"
                )

    # Conditional formatting: type / formula / priority / stop_if_true / color.
    cf_pairs = zip(
        ranges["design"]["conditional_formatting"],
        ranges["conditional_formatting"],
        strict=False,
    )
    for expected, actual in cf_pairs:
        for key in ("type", "formula1", "priority", "stop_if_true", "interior_color"):
            if actual[key] != expected[key]:
                failures.append(
                    f"{RANGES_FIXTURE}: CF {expected['range']} {key} "
                    f"expected {expected[key]!r} got {actual[key]!r}"
                )

    table = ranges["list_object"]
    design_table = ranges["design"]["list_object"]
    if table["name"] != design_table["name"]:
        failures.append(f"{RANGES_FIXTURE}: ListObject name mismatch")
    if table["range"].replace("$", "") != design_table["range"]:
        failures.append(f"{RANGES_FIXTURE}: ListObject range mismatch ({table['range']})")
    if table["headers"] != design_table["headers"]:
        failures.append(f"{RANGES_FIXTURE}: ListObject headers mismatch")

    pivots = manifest["fixtures"][PIVOTS_FIXTURE]
    if pivots["pivot_mismatches"]:
        failures.append(f"{PIVOTS_FIXTURE}: {len(pivots['pivot_mismatches'])} pivot mismatch(es)")

    # Shared-cache invariant: ptA and ptB must report the same cache index.
    observed = {name: record["cache_index"] for name, record in pivots["pivot_tables"].items()}
    shared = pivots["design"]["shared_cache"]
    shared_indices = {observed[name] for name in shared["pivot_tables"]}
    if len(shared_indices) != 1 or shared_indices != {shared["cache_index"]}:
        failures.append(f"{PIVOTS_FIXTURE}: shared cache index mismatch ({shared_indices})")

    # Source types must all be local (xlDatabase) and no Data Model is present.
    for cache in pivots["caches"]:
        if cache["source_type"] != XL_SOURCE_DATABASE:
            failures.append(f"{PIVOTS_FIXTURE}: cache {cache['index']} source type not database")

    return failures


def _run(dest_dir: Path) -> int:
    """Build both fixtures, verify, then copy them into ``dest_dir``."""

    pythoncom.CoInitializeEx(pythoncom.COINIT_APARTMENTTHREADED)
    app = win32com.client.DispatchEx("Excel.Application")
    app.Visible = False
    exit_code = 0
    tmp_dir = Path(tempfile.mkdtemp(prefix="build_phase2_"))
    try:
        ranges_path = tmp_dir / RANGES_FIXTURE
        pivots_path = tmp_dir / PIVOTS_FIXTURE

        ranges_notes = _build_ranges_cells_project(app, ranges_path)
        pivots_notes = _build_pivottables_project(app, pivots_path)

        ranges_block = _collect_ranges_cells(app, ranges_path)
        pivots_block = _collect_pivots(app, pivots_path)

        manifest = _build_manifest(
            app=app,
            ranges_path=ranges_path,
            pivots_path=pivots_path,
            ranges_block=ranges_block,
            pivots_block=pivots_block,
            ranges_notes=ranges_notes,
            pivots_notes=pivots_notes,
        )
        failures = _verify_manifest(manifest)

        dest_dir.mkdir(parents=True, exist_ok=True)
        shutil.copy2(ranges_path, dest_dir / RANGES_FIXTURE)
        shutil.copy2(pivots_path, dest_dir / PIVOTS_FIXTURE)

        # Re-hash the *committed* copies so the manifest describes what is stored.
        manifest["fixtures"][RANGES_FIXTURE]["sha256"] = _sha256(dest_dir / RANGES_FIXTURE)
        manifest["fixtures"][PIVOTS_FIXTURE]["sha256"] = _sha256(dest_dir / PIVOTS_FIXTURE)

        manifest_path = dest_dir / MANIFEST_NAME
        manifest_path.write_text(
            json.dumps(manifest, indent=2, sort_keys=False) + "\n", encoding="utf-8"
        )

        print(f"[built] {RANGES_FIXTURE} -> {dest_dir / RANGES_FIXTURE}")
        print(f"[built] {PIVOTS_FIXTURE} -> {dest_dir / PIVOTS_FIXTURE}")
        print(f"[manifest] {manifest_path}")
        print(
            f"[verify] ranges_cells={len(ranges_block['cells'])} cells, "
            f"pivots={len(pivots_block['pivot_tables'])} tables, "
            f"caches={len(pivots_block['caches'])}"
        )
        if failures:
            exit_code = 1
            for failure in failures:
                print(f"[verify] FAILED: {failure}")
        else:
            print("[verify] OK: readback matches the design oracle")
    finally:
        shutil.rmtree(tmp_dir, ignore_errors=True)
        with contextlib.suppress(Exception):
            app.Quit()
        del app
        pythoncom.CoUninitialize()

    print("[done] phase2 fixtures written to", dest_dir)
    return exit_code


def main(argv: list[str] | None = None) -> int:
    """CLI entry point (optionally overridable destination for local checks)."""

    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument(
        "--dest",
        type=Path,
        default=FIXTURES_DIR,
        help="destination directory for the generated fixtures (default: tests/fixtures)",
    )
    args = parser.parse_args(argv)
    return _run(args.dest)


if __name__ == "__main__":
    sys.exit(main())
